# R/property-values.R
# Manual file - NOT generated by orchestrate.R
# The checks a property setter makes on the value it is given.
#
# cpp11 already refuses a vector of the wrong length. What it cannot see is
# the coercion a setter does first: as.double("abc") is NA with a warning, and
# as.character(5) is "5", so without these a wrong type reaches GDAL as a
# value nobody meant. Each returns the value in the type the binding wants, or
# raises, naming the property.

property_number <- function(value, name, na = FALSE) {
  ok <- length(value) == 1L &&
    (is.numeric(value) || (na && is.logical(value) && is.na(value)))
  if (!ok || (!na && is.na(value))) {
    stop(sprintf("`@%s` must be a single %snumber, not %s", name,
                 if (na) "" else "non-missing ", describe_value(value)),
         call. = FALSE)
  }
  # R's NA is a NaN with a payload; GDAL can hold the payload in memory, but
  # a file stores only NaN, so a missing value is passed as plain NaN.
  if (is.na(value)) NaN else as.double(value)
}

property_integer <- function(value, name) {
  if (!(length(value) == 1L && is.numeric(value) && !is.na(value) &&
        value == round(value))) {
    stop(sprintf("`@%s` must be a single whole number, not %s", name, describe_value(value)),
         call. = FALSE)
  }
  as.integer(value)
}

property_logical <- function(value, name) {
  if (!(length(value) == 1L && is.logical(value) && !is.na(value))) {
    stop(sprintf("`@%s` must be TRUE or FALSE, not %s", name, describe_value(value)),
         call. = FALSE)
  }
  value
}

property_string <- function(value, name) {
  if (!(length(value) == 1L && is.character(value) && !is.na(value))) {
    stop(sprintf("`@%s` must be a single string, not %s", name, describe_value(value)),
         call. = FALSE)
  }
  value
}

describe_value <- function(value) {
  if (is.null(value)) {
    return("NULL")
  }
  type <- typeof(value)
  if (length(value) == 1L && is.atomic(value)) {
    if (is.na(value)) {
      return(sprintf("a missing %s value", type))
    }
    return(sprintf("%s %s value", article(type), type))
  }
  sprintf("%s %s vector of length %d", article(type), type, length(value))
}

article <- function(word) if (grepl("^[aeiou]", word)) "an" else "a"
